create table if not exists public.ils_professional_security_reviewer_authorizations (id uuid primary key default gen_random_uuid(), user_id uuid not null, reviewer_role text not null, authorization_status text not null check(authorization_status in ('PENDING','ACTIVE','SUSPENDED','REVOKED')), identity_verified boolean not null default false, security_training_verified boolean not null default false, assigned_by uuid, valid_from timestamptz, valid_until timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id)); alter table public.ils_professional_security_reviewer_authorizations enable row level security; alter table public.ils_professional_security_reviewer_authorizations force row level security; revoke all on public.ils_professional_security_reviewer_authorizations from anon,authenticated; create table if not exists public.ils_professional_security_reviewer_gate_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_reviewer_gate_tests enable row level security; alter table public.ils_professional_security_reviewer_gate_tests force row level security; revoke all on public.ils_professional_security_reviewer_gate_tests from anon,authenticated; insert into public.ils_professional_security_reviewer_gate_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('MISSING_AUTH','BLOCK','BLOCK',true,'Reviewer authorization requires an authenticated identity.'),('NO_REVIEWER_RECORD','BLOCK','BLOCK',true,'No explicit authorization means no security-review capability.'),('PENDING_REVIEWER','BLOCK','BLOCK',true,'Pending authorization cannot approve security actions.'),('SUSPENDED_REVIEWER','BLOCK','BLOCK',true,'Suspended authorization cannot approve security actions.'),('REVOKED_REVIEWER','BLOCK','BLOCK',true,'Revoked authorization cannot approve security actions.'),('IDENTITY_UNVERIFIED','BLOCK','BLOCK',true,'Identity verification is mandatory.'),('TRAINING_UNVERIFIED','BLOCK','BLOCK',true,'Required security training verification is mandatory.'),('WRONG_ROLE','BLOCK','BLOCK',true,'Only explicitly permitted security-reviewer roles can approve.'),('EXPIRED_AUTHORIZATION','BLOCK','BLOCK',true,'Authorization validity window is enforced.'),('VALID_REVIEWER','ALLOW','ALLOW',true,'Active, verified, trained and currently authorized reviewer may review.'),('SELF_APPROVAL','BLOCK','BLOCK',true,'Reviewer cannot approve an action affecting their own professional identity.'),('CLIENT_AS_REVIEWER','BLOCK','BLOCK',true,'Customer/client identity cannot be treated as security reviewer.');